+
+function RelationshipActions({ partyId, displayName, initial }: {
+  partyId: number; displayName: string; initial: SocialRelationship;
+}) {
+  const { session } = useSession();
+  const qc = useQueryClient();
+  const root = ['social-v2', session?.partyId];
